package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.TimeZone;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for DurationFormatUtils.formatDuration
 */
public class DurationFormatUtils_formatDuration_TriageGen1Test {

    @Test
    public void testFormatDuration_AllTokens_WithPadding() {
        // 1 day, 2 hours, 3 minutes, 4 seconds, 5 milliseconds
        // (1 * 86400000) + (2 * 3600000) + (3 * 60000) + (4 * 1000) + 5 = 93784005
        long millis = 93784005L;
        String format = "d' days 'H' hours 'm' minutes 's' seconds 'S' ms";
        String result = DurationFormatUtils.formatDuration(millis, format, true);
        assertEquals("1 days 02 hours 03 minutes 04 seconds 005 ms", result);
    }

    @Test
    public void testFormatDuration_AllTokens_NoPadding() {
        long millis = 93784005L;
        String format = "d' days 'H' hours 'm' minutes 's' seconds 'S' ms";
        String result = DurationFormatUtils.formatDuration(millis, format, false);
        assertEquals("1 days 2 hours 3 minutes 4 seconds 5 ms", result);
    }

    @Test
    public void testFormatDuration_OnlyHoursAndMinutes() {
        // 2 hours, 30 minutes = 7200000 + 1800000 = 9000000
        long millis = 9000000L;
        String format = "H'h 'm'm'";
        String result = DurationFormatUtils.formatDuration(millis, format, true);
        assertEquals("02h 30m", result);
    }

    @Test
    public void testFormatDuration_OnlySeconds() {
        long millis = 45000L;
        String format = "s's'";
        String result = DurationFormatUtils.formatDuration(millis, format, false);
        assertEquals("45s", result);
    }

    @Test
    public void testFormatDuration_OnlyMilliseconds() {
        long millis = 123L;
        String format = "S'ms'";
        String result = DurationFormatUtils.formatDuration(millis, format, true);
        assertEquals("123ms", result);
    }

    @Test
    public void testFormatDuration_DaysOnly() {
        long millis = 172800000L; // 2 days
        String format = "d'd'";
        String result = DurationFormatUtils.formatDuration(millis, format, false);
        assertEquals("2d", result);
    }

    @Test
    public void testFormatDuration_ZeroMillis() {
        long millis = 0L;
        String format = "H'h 'm'm' 's's'";
        String result = DurationFormatUtils.formatDuration(millis, format, true);
        assertEquals("00h 00m 00s", result);
    }

    @Test
    public void testFormatDuration_LargeMillis() {
        // 10 days
        long millis = 10L * 24 * 60 * 60 * 1000;
        String format = "d'd'";
        String result = DurationFormatUtils.formatDuration(millis, format, false);
        assertEquals("10d", result);
    }

    @Test
    public void testFormatDuration_MixedTokens() {
        // 1 hour, 1 second
        long millis = 3601000L;
        String format = "H'h 's's'";
        String result = DurationFormatUtils.formatDuration(millis, format, true);
        assertEquals("01h 01s", result);
    }

    @Test
    public void testFormatDuration_NoTokensInFormat() {
        // If format contains no recognized tokens, it should return the format string as is
        long millis = 1000L;
        String format = "no tokens here";
        String result = DurationFormatUtils.formatDuration(millis, format, false);
        assertEquals("no tokens here", result);
    }
}
